input.command:
ls node_modules/.bin | grep -E "tsc|tsx"; cat > /tmp/probe.mjs <<'EOF'
import xrpl from 'xrpl';
const w = xrpl.Wallet.fromSeed('<TESTNET_SEED_REDACTED>');
console.log('derived', w.classicAddress);
const c = new xrpl.Client('wss://s.altnet.rippletest.net:51233'); await c.connect();
const si = await c.request({command:'server_info'}); console.log(JSON.stringify(si.result.info.validated_ledger), si.result.info.build_version);
const ai = await c.request({command:'account_info', account:w.classicAddress, ledger_index:'validated', signer_lists:true}); console.log(JSON.stringify(ai.result));
const ao = await c.request({command:'account_objects', account:w.classicAddress, ledger_index:'validated'}); console.log(JSON.stringify(ao.result.account_objects));
const f = await c.request({command:'feature'}); for (const [k,v] of Object.entries(f.result.features)) if (/MPT|Clawback|Escrow|Dynamic|Single|Permission/i.test(v.name)) console.log(v.name, v.enabled);
await c.disconnect();
EOF
cp /tmp/probe.mjs ./probe.mjs && node probe.mjs; rm probe.mjs

