  if (typeof address !== 'string' || !isValidClassicAddress(address)) {
    throw new ValidationError(`Invalid ${label}: ${JSON.stringify(address)}`);
  }
}

export function assertIssuanceId(id: string): void {
  if (typeof id !== 'string' || !/^[0-9A-F]{48}$/.test(id)) {
    throw new ValidationError(`Invalid MPT issuance ID (expected 48 uppercase hex chars): ${JSON.stringify(id)}`);
